const config = {
  "previewFeatures": [],
  "clientVersion": "7.8.0",
  "engineVersion": "3c6e192761c0362d496ed980de936e2f3cebcd3a",
  "activeProvider": "mysql",
  "inlineSchema": "// Aqui eu configurei a geração do client para uma pasta customizada dentro de src,\n// garantindo compatibilidade com o Docker do projeto e seguindo o padrão do microsserviço Locador.\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../src/generated/prisma\"\n}\n\n// Defini o MySQL como provider e puxei a variável de ambiente segura.\ndatasource db {\n  provider = \"mysql\"\n}\n\n// ---------------------------------------------------------\n// ENUMS (Mapeados exatamente conforme o script do P.O.)\n// ---------------------------------------------------------\n\nenum classificacao_enum {\n  RESIDENCIAL\n  COMERCIAL\n  RURAL\n  INDUSTRIAL\n}\n\nenum tipologia_enum {\n  CASA\n  APARTAMENTO\n  TERRENO\n  SALA_COMERCIAL\n  GALPAO\n}\n\nenum status_imovel_enum {\n  DISPONIVEL\n  ALUGADO\n  VENDIDO\n  INATIVO\n}\n\nenum status_contrato_enum {\n  ATIVO\n  ENCERRADO\n  CANCELADO\n}\n\nenum tipo_despesa_enum {\n  ALUGUEL\n  CONDOMINIO\n  IPTU\n  TAXA_BOMBEIRO\n  SEGURO_INCENDIO\n  MANUTENCAO\n  OUTRA\n}\n\nenum status_despesa_enum {\n  PAGA\n  EM_ABERTO\n}\n\nenum indice_reajuste_enum {\n  IGPM\n  IPCA\n  INCC\n  OUTRO\n}\n\n// ---------------------------------------------------------\n// TABELAS\n// ---------------------------------------------------------\n\nmodel endereco {\n  // Criei a tabela de endereço espelhando os índices do script original para otimizar as buscas\n  id     Int      @id @default(autoincrement())\n  rua    String   @db.VarChar(150)\n  numero String?  @db.VarChar(20)\n  bairro String   @db.VarChar(100)\n  cidade String   @db.VarChar(100)\n  estado String   @db.Char(2)\n  cep    String   @db.VarChar(20)\n  imovel imovel[]\n\n  @@index([cidade], map: \"idx_cidade\")\n  @@index([bairro], map: \"idx_bairro\")\n  @@index([estado], map: \"idx_estado\")\n}\n\nmodel imovel {\n  // O relacionamento com endereço foi configurado com Delete Cascade, \n  // garantindo integridade referencial conforme exigido pelo professor.\n  id                Int                @id @default(autoincrement())\n  idEndereco        Int\n  inscricaoIPTU     String?            @unique @db.VarChar(50)\n  inscricaoBombeiro String?            @db.VarChar(50)\n  metragem          String?            @db.VarChar(50)\n  dataCadastro      DateTime           @default(now()) @db.DateTime(0)\n  classificacao     classificacao_enum\n  tipologia         tipologia_enum\n  status            status_imovel_enum\n\n  endereco          endereco            @relation(fields: [idEndereco], references: [id], onDelete: Cascade, onUpdate: Restrict)\n  contratolocacao   contratolocacao[]\n  propriedadeimovel propriedadeimovel[]\n  memoriacalculo    memoriacalculo[]\n\n  @@index([dataCadastro], map: \"idx_dataCadastro\")\n  @@index([status], map: \"idx_status\")\n  @@index([idEndereco], map: \"idEndereco\")\n}\n\nmodel propriedadeimovel {\n  // Aqui eu mapeei o idLocador como BigInt e o percentual como Decimal(5,2), \n  // travando os tipos exatos do banco de dados relacional.\n  id                     Int     @id @default(autoincrement())\n  idImovel               Int\n  idLocador              BigInt\n  percentualParticipacao Decimal @db.Decimal(5, 2)\n  imovel                 imovel  @relation(fields: [idImovel], references: [id], onDelete: Cascade, onUpdate: Restrict)\n\n  @@index([idImovel], map: \"idImovel\")\n}\n\nmodel contratolocacao {\n  // Tipifiquei o contratoDigitalizado como Bytes (LONGBLOB no MySQL) para suportar\n  // os uploads de PDF que passaremos através do FileInterceptor.\n  id                   BigInt               @id @default(autoincrement())\n  idImovel             Int\n  idLocador            BigInt\n  idLocatario          BigInt\n  dataInicio           DateTime             @db.Date\n  dataFim              DateTime?            @db.Date\n  dataReajuste         DateTime?            @db.Date\n  valorAluguel         Decimal              @db.Decimal(10, 2)\n  status               status_contrato_enum @default(ATIVO)\n  contratoDigitalizado Bytes?\n  imovel               imovel               @relation(fields: [idImovel], references: [id], onUpdate: Restrict)\n  comissao             Decimal              @db.Decimal(10, 2)\n  despesa              despesa[]\n  reajustecontrato     reajustecontrato[]\n  memoriacalculo       memoriacalculo[]\n\n  @@index([idImovel], map: \"idImovel\")\n}\n\nmodel reajustecontrato {\n  // Histórico dos reajustes anuais aplicados ao contrato. \"Aplicar\" um reajuste grava esta linha E\n  // atualiza contratolocacao.valorAluguel/dataReajuste (dataReajuste avança 1 ano) na mesma transação,\n  // então o valor vigente do contrato sempre reflete o último reajuste aplicado.\n  id              BigInt               @id @default(autoincrement())\n  idContrato      BigInt\n  dataReajuste    DateTime             @db.Date\n  indice          indice_reajuste_enum\n  percentual      Decimal              @db.Decimal(7, 4)\n  valorAnterior   Decimal              @db.Decimal(10, 2)\n  valorNovo       Decimal              @db.Decimal(10, 2)\n  observacao      String?              @db.VarChar(255)\n  criadoEm        DateTime             @default(now()) @db.DateTime(0)\n  contratolocacao contratolocacao      @relation(fields: [idContrato], references: [id], onDelete: Cascade, onUpdate: Restrict)\n\n  @@index([idContrato], map: \"idx_reajustecontrato_idContrato\")\n}\n\nmodel memoriacalculo {\n  // Registro imutável de cada geração da \"Memória de Cálculo\" (rateio do aluguel entre os proprietários\n  // de um imóvel, num mês/competência). Uma vez gerado, o documento não deve mudar retroativamente:\n  // por isso os dados de exibição (nome do locador, conta bancária) ficam FOTOGRAFADOS aqui, e não\n  // apontam por FK para os cadastros vivos (que podem ser editados depois em api-locador/api-locatario).\n  id               Int      @id @default(autoincrement())\n  idContrato       BigInt\n  idImovel         Int\n  competencia      DateTime @db.Date // sempre o dia 1 do mês de referência\n  valorAluguelBase Decimal  @db.Decimal(10, 2) // valorAluguel do contrato usado nesta geração\n\n  // Fotografia da conta de depósito escolhida (a tabela real vive no serviço de locatários)\n  idContaBancaria       Int?\n  contaDescricao        String? @db.VarChar(100)\n  contaBanco            String? @db.VarChar(100)\n  contaAgencia          String? @db.VarChar(20)\n  contaNumero           String? @db.VarChar(30)\n  contaTipoChavePix     String? @db.VarChar(20)\n  contaChavePix         String? @db.VarChar(140)\n  contaTitular          String? @db.VarChar(150)\n  contaDocumentoTitular String? @db.VarChar(20)\n\n  // Fotografia do reajuste, quando a competência coincide com um reajuste aplicado nesta geração\n  reajusteIndice        indice_reajuste_enum?\n  reajustePercentual    Decimal?              @db.Decimal(7, 4)\n  reajusteValorAnterior Decimal?              @db.Decimal(10, 2)\n\n  totalAPagar        Decimal  @db.Decimal(10, 2)\n  geradoPorUsuarioId Int\n  criadoEm           DateTime @default(now()) @db.DateTime(0)\n\n  contratolocacao contratolocacao      @relation(fields: [idContrato], references: [id], onUpdate: Restrict)\n  imovel          imovel               @relation(fields: [idImovel], references: [id], onUpdate: Restrict)\n  itens           memoriacalculoitem[]\n\n  @@unique([idContrato, competencia], map: \"uq_memoriacalculo_contrato_competencia\")\n  @@index([idImovel], map: \"idx_memoriacalculo_idImovel\")\n}\n\nmodel memoriacalculoitem {\n  // Uma linha por proprietário dentro da memória (o \"bloco\" de cada locador na planilha de referência).\n  id                     Int            @id @default(autoincrement())\n  idMemoriaCalculo       Int\n  idLocador              BigInt\n  nomeLocador            String         @db.VarChar(150)\n  documentoLocador       String?        @db.VarChar(20)\n  percentualParticipacao Decimal        @db.Decimal(5, 2)\n  valorAluguel           Decimal        @db.Decimal(10, 2) // rateio: valorAluguelBase * percentual\n  valorReembolsos        Decimal        @default(0) @db.Decimal(10, 2) // despesas extras atribuídas a este locador\n  valorDescontos         Decimal        @default(0) @db.Decimal(10, 2)\n  baseCalculoIrrf        Decimal        @db.Decimal(10, 2)\n  valorIrrf              Decimal        @db.Decimal(10, 2)\n  valorAPagar            Decimal        @db.Decimal(10, 2)\n  // Lista curta {idDespesa?, tipo, descricao, valor, aplicacao} das despesas extras atribuídas a este\n  // locador, só para exibição/auditoria — os valores oficiais já estão persistidos nas colunas acima.\n  detalhesExtras         Json?\n  memoriacalculo         memoriacalculo @relation(fields: [idMemoriaCalculo], references: [id], onDelete: Cascade, onUpdate: Restrict)\n\n  @@index([idMemoriaCalculo], map: \"idx_memoriacalculoitem_idMemoriaCalculo\")\n}\n\nmodel despesa {\n  // O comprovantePagamento também foi mapeado como Bytes para fechar o ecossistema financeiro.\n  id                   BigInt              @id @default(autoincrement())\n  idContratoLocacao    BigInt\n  descricao            String              @db.VarChar(255)\n  valor                Decimal             @db.Decimal(10, 2)\n  tipo                 tipo_despesa_enum\n  dataVencimento       DateTime            @db.Date\n  dataPagamento        DateTime?           @db.Date\n  status               status_despesa_enum @default(EM_ABERTO)\n  comprovantePagamento Bytes?\n  contratolocacao      contratolocacao     @relation(fields: [idContratoLocacao], references: [id], onDelete: Cascade, onUpdate: Restrict)\n\n  @@index([idContratoLocacao], map: \"idContratoLocacao\")\n}\n\nmodel tabelairrf {\n  // Cada registro é uma VERSÃO da tabela progressiva do IRRF. Só o início da vigência é gravado:\n  // o fim é sempre \"início da próxima versão - 1 dia\", o que impede sobreposição ou lacuna entre versões.\n  // Nenhum valor fiscal fica no código: quem cadastra as versões é o ADMIN, pela tela de gerenciamento.\n  id                    Int         @id @default(autoincrement())\n  vigenciaInicio        DateTime    @unique(map: \"uq_tabelairrf_vigenciaInicio\") @db.Date\n  descricao             String?     @db.VarChar(255)\n  deducaoDependente     Decimal     @db.Decimal(10, 2)\n  // Redutor opcional (isenção até um teto e redução gradual acima dele). Os quatro campos são\n  // preenchidos juntos ou ficam todos nulos, quando o cálculo usa só as faixas + dependentes.\n  redutorLimiteIsencao  Decimal?    @db.Decimal(10, 2)\n  redutorLimiteSuperior Decimal?    @db.Decimal(10, 2)\n  redutorConstante      Decimal?    @db.Decimal(10, 2)\n  redutorCoeficiente    Decimal?    @db.Decimal(10, 6)\n  criadoEm              DateTime    @default(now()) @db.DateTime(0)\n  atualizadoEm          DateTime    @default(now()) @updatedAt @db.DateTime(0)\n  faixairrf             faixairrf[]\n}\n\nmodel faixairrf {\n  // valorDe e valorAte são inclusivos e em reais. Como na tabela oficial, o valorDe de uma faixa é\n  // o valorAte da anterior + 0,01. A última faixa não tem teto (valorAte nulo).\n  // A alíquota é guardada em percentual (7.50 = 7,5%), igual ao percentualParticipacao dos proprietários.\n  id              Int        @id @default(autoincrement())\n  idTabela        Int\n  ordem           Int\n  valorDe         Decimal    @db.Decimal(10, 2)\n  valorAte        Decimal?   @db.Decimal(10, 2)\n  aliquota        Decimal    @db.Decimal(5, 2)\n  parcelaADeduzir Decimal    @db.Decimal(10, 2)\n  tabelairrf      tabelairrf @relation(fields: [idTabela], references: [id], onDelete: Cascade, onUpdate: Restrict)\n\n  @@unique([idTabela, ordem], map: \"uq_faixairrf_tabela_ordem\")\n}\n"
}

